//! ONNX engine behavior. The value-level test needs `--features
//! onnx` and uses the tiny `Y = Relu(X)` fixture generated by
//! `tools/make-test-model.py`.

#[cfg(feature = "onnx")]
use edge_core::GpuStream;
use edge_core::{ModelConfig, Platform};
use platform_sim::SimPlatform;
use std::path::PathBuf;

fn fixture_cfg() -> ModelConfig {
    ModelConfig {
        enabled: true,
        path: Some(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/relu.onnx")),
        decoder: Default::default(),
        input_color: Default::default(),
        input_normalize: Default::default(),
        pad_value: 114,
        input_colorspace: Default::default(),
        precision: Default::default(),
        device: None,
        input_width: 4,
        input_height: 4,
        num_classes: 80,
        score_threshold: 0.25,
        iou_threshold: 0.45,
        max_nms: 300,
        top_k: 100,
    }
}

#[cfg(feature = "onnx")]
#[test]
fn onnx_engine_runs_fixture_and_returns_relu_values() {
    let platform = SimPlatform;
    let mut engine = platform
        .engine(&fixture_cfg())
        .expect("load fixture model")
        .wait_ready(std::time::Duration::from_secs(5))
        .expect("sim engine is ready immediately");

    // Fill the input binding the way a preprocessor would.
    let input = &mut engine.input_bindings()[0];
    assert_eq!(input.spec.shape, vec![1, 3, 4, 4]);
    let slice = input.as_f32_slice_mut().expect("host F32 input");
    assert_eq!(slice.len(), 48);
    for (i, v) in slice.iter_mut().enumerate() {
        *v = i as f32 - 24.0; // -24.0 ..= 23.0
    }

    engine.infer(&GpuStream::noop()).expect("infer");

    let output = &engine.output_bindings()[0];
    assert_eq!(output.spec.shape, vec![1, 3, 4, 4]);
    let data = output.as_f32_slice().expect("host F32 output");
    let expected: Vec<f32> = (0..48).map(|i| (i as f32 - 24.0).max(0.0)).collect();
    assert_eq!(data, expected.as_slice(), "output must be relu(input)");
}

/// Item 13: the fixture declares `[1, 3, 4, 4]`; a config that
/// says 8x8 must be refused at load, not at the first infer.
#[cfg(feature = "onnx")]
#[test]
fn onnx_engine_rejects_config_shape_mismatch_at_load() {
    let platform = SimPlatform;
    let mut cfg = fixture_cfg();
    cfg.input_width = 8;
    cfg.input_height = 8;
    match platform.engine(&cfg) {
        Ok(_) => panic!("shape mismatch must fail to load"),
        Err(e) => assert!(
            e.to_string().contains("does not match"),
            "error must describe the mismatch: {e}"
        ),
    }
}

#[cfg(feature = "onnx")]
#[test]
fn onnx_engine_rejects_missing_model_with_path_in_error() {
    let platform = SimPlatform;
    let mut cfg = fixture_cfg();
    cfg.path = Some(PathBuf::from("/nonexistent/model.onnx"));
    match platform.engine(&cfg) {
        Ok(_) => panic!("missing model must fail to load"),
        Err(e) => assert!(
            e.to_string().contains("/nonexistent/model.onnx"),
            "error must name the path: {e}"
        ),
    }
}

#[cfg(not(feature = "onnx"))]
#[test]
fn model_path_without_onnx_feature_fails_clearly() {
    let platform = SimPlatform;
    match platform.engine(&fixture_cfg()) {
        Ok(_) => panic!("model.path must not silently fall back to the sim engine"),
        Err(e) => assert!(
            e.to_string().contains("--features onnx"),
            "error must name the missing feature: {e}"
        ),
    }
}
